& {
"'$probeState=[pscustomobject]@{writes=0;releases=0}
function Complete-StoreCommit { param($Commit,[switch]$Findings) $probeState.writes++ }
function Exit-StoreCommit { param($Commit) $probeState.releases++;$Commit.Acquired=$false }
$mark=ConvertFrom-Json '"'{\"n\":1,\"consult_id\":\"11111111-2222-4333-8444-555555555555\",\"rating_rev\":5,\"when\":\"2026-10-08T10:00:00Z\"}'
"'$commit=[pscustomobject]@{Acquired=$true;Findings=[pscustomobject]@{ratings=@($mark)}}
$first=Set-RatingTelemetrySent -Mark $mark -Sent 1791453600 -Commit $commit
$second=Set-RatingTelemetrySent -Mark $mark -Sent 1791453601 -Commit $commit
[pscustomobject]@{first_result=$first;second_result=$second;store_writes=$probeState.writes;lock_releases=$probeState.releases;lock_still_acquired=$commit.Acquired;marker=$mark.telemetry_sent} | ConvertTo-Json -Compress
}
